<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sorting Visualizer</title>
<style>
  :root{
    --bg:#0e1116;
    --panel:#161b22;
    --edge:#262d38;
    --fg:#e6edf3;
    --muted:#8b949e;
    --accent:#58a6ff;
    --cmp:#f2cc60;
    --swap:#ff7b72;
    --ok:#3fb950;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 600px at 50% -10%, #18202b 0%, var(--bg) 60%);
    color:var(--fg);
    font:14px/1.45 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;flex-direction:column;align-items:center;
    padding:24px 16px 32px;
  }
  h1{
    font-size:18px;letter-spacing:.14em;text-transform:uppercase;
    margin:0 0 16px;color:var(--muted);font-weight:600;
  }
  .wrap{width:100%;max-width:980px}
  .panel{
    background:linear-gradient(180deg,#171d26,#12171e);
    border:1px solid var(--edge);
    border-radius:14px;
    padding:14px;
    box-shadow:0 18px 40px rgba(0,0,0,.45);
  }
  #bars{
    height:360px;
    display:flex;
    align-items:flex-end;
    gap:2px;
    padding:8px;
    background:#0b0f14;
    border:1px solid var(--edge);
    border-radius:10px;
    overflow:hidden;
  }
  .bar{
    flex:1 1 0;
    min-width:2px;
    background:linear-gradient(180deg,#4a8fd6,#2b5f96);
    border-radius:3px 3px 0 0;
    transition:height .08s linear, background-color .08s linear;
  }
  .bar.cmp{background:linear-gradient(180deg,#ffe08a,var(--cmp))}
  .bar.swap{background:linear-gradient(180deg,#ff9b95,var(--swap))}
  .bar.done{background:linear-gradient(180deg,#68e08a,#2f9147)}
  .controls{
    display:flex;flex-wrap:wrap;gap:10px;align-items:center;
    margin-top:14px;
  }
  button{
    appearance:none;cursor:pointer;
    background:#20293a;color:var(--fg);
    border:1px solid #33405a;
    padding:9px 16px;border-radius:9px;
    font-size:13px;font-weight:600;letter-spacing:.04em;
    transition:transform .06s ease, background .15s ease, border-color .15s ease;
  }
  button:hover{background:#2a3549;border-color:var(--accent)}
  button:active{transform:translateY(1px)}
  button[disabled]{opacity:.45;cursor:not-allowed}
  #sort{background:#1f3d63;border-color:#2f5f96}
  #sort:hover{background:#27507f}
  label.rng{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}
  input[type=range]{width:130px;accent-color:var(--accent)}
  .spacer{flex:1}
  #status{
    color:var(--muted);font-size:12px;font-variant-numeric:tabular-nums;
    white-space:nowrap;
  }
  #status b{color:var(--fg);font-weight:600}
  .legend{margin-top:8px;color:#6e7681;font-size:11px}
</style>
</head>
<body>
<div class="wrap">
  <h1>Sorting Visualizer &mdash; Bubble Sort</h1>
  <div class="panel">
    <div id="bars"></div>
    <div class="controls">
      <button id="sort">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
      <label class="rng">Size <input id="size" type="range" min="8" max="120" value="40"></label>
      <label class="rng">Speed <input id="speed" type="range" min="1" max="400" value="120"></label>
      <div class="spacer"></div>
      <div id="status">steps <b>0</b></div>
    </div>
    <div class="legend">Compared &middot; swapped &middot; locked bars are highlighted while sorting.</div>
  </div>
</div>

<script>
(function(){
  "use strict";

  var barsEl   = document.getElementById('bars');
  var sortBtn  = document.getElementById('sort');
  var shufBtn  = document.getElementById('shuffle');
  var resetBtn = document.getElementById('reset');
  var sizeEl   = document.getElementById('size');
  var speedEl  = document.getElementById('speed');
  var statusEl = document.getElementById('status');

  var arr = [];          // current array
  var initial = [];      // snapshot for reset
  var bars = [];         // bar elements

  // bubble sort state
  var i = 0, j = 0, swapped = false, done = false, steps = 0;
  var hi = [-1,-1], lastSwap = false;
  var timer = null;

  function randArray(n){
    var a = [];
    for (var k = 0; k < n; k++) a.push(Math.floor(Math.random()*99) + 1);
    return a;
  }

  function resetSortState(){
    i = 0; j = 0; swapped = false; steps = 0;
    hi = [-1,-1]; lastSwap = false;
    done = isSorted(arr);
  }

  function isSorted(a){
    for (var k = 1; k < a.length; k++) if (a[k-1] > a[k]) return false;
    return true;
  }

  function build(){
    barsEl.innerHTML = '';
    bars = [];
    for (var k = 0; k < arr.length; k++){
      var d = document.createElement('div');
      d.className = 'bar';
      barsEl.appendChild(d);
      bars.push(d);
    }
    render();
  }

  function render(){
    var max = 1;
    for (var k = 0; k < arr.length; k++) if (arr[k] > max) max = arr[k];
    var n = arr.length;
    for (var k = 0; k < n; k++){
      var b = bars[k];
      if (!b) continue;
      b.style.height = Math.max(2, (arr[k] / max) * 100) + '%';
      b.title = String(arr[k]);
      var cls = 'bar';
      if (done){
        cls += ' done';
      } else if (k === hi[0] || k === hi[1]){
        cls += lastSwap ? ' swap' : ' cmp';
      } else if (i > 0 && k >= n - i){
        cls += ' done';
      }
      b.className = cls;
    }
    statusEl.innerHTML = 'steps <b>' + steps + '</b>' +
      (done ? ' &middot; <span style="color:var(--ok)">sorted</span>' : '');
  }

  // ---- one comparison/step of bubble sort ----
  function sortStep(){
    var n = arr.length;
    if (done || n < 2){
      done = true;
      hi = [-1,-1];
      render();
      return true;
    }
    steps++;
    lastSwap = false;
    hi = [j, j+1];
    if (arr[j] > arr[j+1]){
      var t = arr[j]; arr[j] = arr[j+1]; arr[j+1] = t;
      swapped = true;
      lastSwap = true;
    }
    j++;
    if (j >= n - 1 - i){
      if (!swapped){
        done = true;
      } else {
        i++; j = 0; swapped = false;
        if (i >= n - 1) done = true;
      }
    }
    if (done){
      // safety: verify, and continue from scratch if somehow not sorted
      if (!isSorted(arr)){
        done = false; i = 0; j = 0; swapped = false;
      } else {
        hi = [-1,-1];
      }
    }
    render();
    return done;
  }

  function stop(){
    if (timer){ clearInterval(timer); timer = null; }
    sortBtn.textContent = 'Sort';
    shufBtn.disabled = false; resetBtn.disabled = false; sizeEl.disabled = false;
  }

  function run(){
    if (timer) { stop(); return; }
    if (done && isSorted(arr)) return;
    sortBtn.textContent = 'Pause';
    shufBtn.disabled = true; resetBtn.disabled = true; sizeEl.disabled = true;
    var tick = function(){
      var perTick = Math.max(1, Math.round(arr.length / 24));
      for (var k = 0; k < perTick; k++){
        if (sortStep()) { stop(); return; }
      }
    };
    var delay = Math.max(0, 405 - Number(speedEl.value));
    timer = setInterval(tick, delay);
  }

  function setArray(a){
    stop();
    arr = Array.prototype.slice.call(a).map(Number);
    initial = arr.slice();
    resetSortState();
    build();
    return arr.slice();
  }

  function shuffle(){
    stop();
    for (var k = arr.length - 1; k > 0; k--){
      var r = Math.floor(Math.random() * (k + 1));
      var t = arr[k]; arr[k] = arr[r]; arr[r] = t;
    }
    initial = arr.slice();
    resetSortState();
    render();
  }

  sortBtn.addEventListener('click', run);
  shufBtn.addEventListener('click', shuffle);
  resetBtn.addEventListener('click', function(){
    stop();
    arr = initial.slice();
    resetSortState();
    render();
  });
  sizeEl.addEventListener('input', function(){
    stop();
    setArray(randArray(Number(sizeEl.value)));
  });
  speedEl.addEventListener('input', function(){
    if (timer){ clearInterval(timer); timer = null; run(); }
  });

  // initial data
  setArray(randArray(Number(sizeEl.value)));

  window.viz = {
    array:    function(){ return arr.slice(); },
    setArray: function(a){ return setArray(a); },
    sortStep: function(){ return sortStep(); },
    sorted:   function(){ return isSorted(arr); },
    shuffle:  shuffle,
    bars:     function(){ return bars.slice(); }
  };
})();
</script>
</body>
</html>
